package com.wedo.backend.task.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="task_assignees") public class TaskAssigneeEntity { @Id private UUID id; @Column(name="task_id",nullable=false) private UUID taskId; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="assigned_by") private UUID assignedBy; @Column(name="assigned_at",nullable=false) private Instant assignedAt; protected TaskAssigneeEntity(){} public TaskAssigneeEntity(UUID id,UUID taskId,UUID userId,UUID assignedBy,Instant at){this.id=id;this.taskId=taskId;this.userId=userId;this.assignedBy=assignedBy;this.assignedAt=at;} public UUID getId(){return id;} public UUID getTaskId(){return taskId;} public UUID getUserId(){return userId;} }
